    { "kind": "street_orientation", "id": "c1", "text": "Broadway cuts diagonally across the Jackson Heights street grid, a relic of a pre-grid colonial-era road.", "street": "BROADWAY", "relation": "diagonal_to_grid" },
    { "kind": "street_orientation", "id": "c2", "text": "Northern Boulevard runs diagonal to the numbered grid, following an older regional route rather than the platted blocks.", "street": "NORTHERN BLVD", "relation": "diagonal_to_grid" },
    { "kind": "street_orientation", "id": "c3", "text": "Roosevelt Avenue slices across the grid at an angle, tracing the path of an earlier road and later the elevated transit line.", "street": "ROOSEVELT AVE", "relation": "diagonal_to_grid" },
    { "kind": "street_orientation", "id": "c4", "text": "Junction Boulevard is diagonal to the grid, marking the historic meeting point of older roads that the grid was later laid over.", "street": "JUNCTION BLVD", "relation": "diagonal_to_grid" },
