    { "kind": "layer_stat", "id": "c8", "text": "The street centerline layer records 1,001 mapped street segments across Jackson Heights.", "layer": "streets_centerline", "field": null, "agg": "count", "expected": 1001, "tolerance": 0 },
    { "kind": "layer_stat", "id": "c9", "text": "Street segments average 32.6 feet in width across the neighborhood.", "layer": "streets_centerline", "field": "st_width", "agg": "mean", "expected": 32.6, "tolerance": 0.1 },
    { "kind": "layer_stat", "id": "c10", "text": "The narrowest mapped street segment is just 6 feet wide, likely a service lane or courtyard access path.", "layer": "streets_centerline", "field": "st_width", "agg": "min", "expected": 6, "tolerance": 0 },
    { "kind": "layer_stat", "id": "c11", "text": "The widest mapped street segment reaches 70 feet, matching the neighborhood's major boulevards.", "layer": "streets_centerline", "field": "st_width", "agg": "max", "expected": 70, "tolerance": 0 }
  ],
  "sections": [
    {
      "title": "Before the Grid: Colonial Roads Across the Meadows",
      "intro": "Long before Jackson Heights was platted into numbered streets and avenues, a handful of regional roads already crossed the farmland and meadows of this part of Queens. Those roads survive today as diagonal scars cutting through an otherwise orderly grid.",
      "cites": ["nyc-lpc", "city-lore"],
      "claim_ids": ["c1", "c2", "c3", "c4"],
      "slides": [
        {
          "title": "Diagonal Survivors",
          "body": "Broadway and Northern Boulevard both run at an angle to the neighborhood's numbered streets and avenues. Neither was designed with the grid — both predate it, carrying forward old travel routes that linked outlying villages before Jackson Heights existed.",
          "map": { "item_id": "81186482d5dd48ca9882593adadd6bfe", "caption": "Hard System Layers: diagonal roads overlaid on the numbered grid." },
          "claim_ids": ["c1", "c2"]
        },
        {
          "title": "A Junction Named for Itself",
          "body": "Roosevelt Avenue and Junction Boulevard likewise ignore the grid's right angles. Junction Boulevard takes its very name from the historic crossing of older roads at this spot — a junction the planned grid simply had to accommodate rather than erase.",
          "map": { "item_id": "81186482d5dd48ca9882593adadd6bfe", "caption": "Hard System Layers: Roosevelt Avenue and Junction Boulevard crossing the grid diagonally." },
          "claim_ids": ["c3", "c4"]
        }
      ]
    },
    {
      "title": "Laying Down the Grid",
      "intro": "Starting in the early twentieth century, the Queensboro Corporation imposed a regular grid of numbered streets and avenues over the remaining farmland, creating the uniform blocks that would define Jackson Heights as a planned garden community.",
      "cites": ["nyc-opendata"],
      "claim_ids": ["c5", "c6", "c7", "c8", "c9"],
      "slides": [
        {
          "title": "Numbers Over Names",
          "body": "34th Avenue, 37th Avenue, and 82nd Street all run parallel to one another and to the grid itself — part of the disciplined, repeatable numbering system that replaced the tangle of old road names with predictable addresses.",
          "map": { "item_id": "865dbb45a3b3455590652560174b9ed9", "caption": "Street & Open Space Profile: parallel numbered avenues and streets forming the grid." },
          "claim_ids": ["c5", "c6", "c7"]
        },
        {
          "title": "A System of 1,001 Segments",
          "body": "The resulting street network comprises 1,001 mapped segments, with widths averaging 32.6 feet — a consistency that let the Queensboro Corporation standardize block depths and, in turn, the size of the courtyards and gardens built behind them.",
          "map": { "item_id": "865dbb45a3b3455590652560174b9ed9", "caption": "Street & Open Space Profile: segment count and width distribution." },
          "claim_ids": ["c8", "c9"]
        }
      ]
    },
    {
      "title": "Open Space as the Grid's Release Valve",
      "intro": "The regularity of the street grid freed up interior block space for parks and private gardens. Travers Park and the famous interior courtyards of Jackson Heights' garden apartment complexes became the neighborhood's answer to dense, gridded blocks.",
      "cites": ["nyc-parks", "city-lore"],
      "claim_ids": ["c9", "c10"],
      "slides": [
        {
          "title": "Travers Park and the Scale of the Block",
          "body": "Travers Park sits within a single grid block, its size set by the dimensions the numbered streets around it establish. The moderate 32.6-foot average street width left enough block interior for this public green space to breathe.",
          "map": { "item_id": "865dbb45a3b3455590652560174b9ed9", "caption": "Street & Open Space Profile: Travers Park within its bounding grid block." },
          "claim_ids": ["c9"]
        },
        {
          "title": "Courtyards Behind the Curb",
          "body": "Some of the narrowest mapped paths, as little as 6 feet wide, are the private lanes and service walks threading between garden apartment buildings — intimate counterpoints to the 70-foot boulevards that frame the neighborhood, together forming a street hierarchy that nests quiet open space inside a busy grid.",
          "map": { "item_id": "865dbb45a3b3455590652560174b9ed9", "caption": "Street & Open Space Profile: narrow interior lanes beside the widest boulevards." },
          "claim_ids": ["c10", "c11"]
        }
      ]
    },
    {
      "title": "A System Shaped by Both",
      "intro": "The diagonal roads that preceded the grid and the grid that absorbed them together produced Jackson Heights' distinctive pattern of streets and open space — each system bending to accommodate the other.",
      "cites": ["nyc-lpc"],
      "claim_ids": ["c1", "c5", "c8"],
      "slides": [
        {
          "title": "Where Diagonal Meets Grid",
          "body": "At points where Broadway crosses the parallel numbered avenues like 34th Avenue, irregular triangular blocks appear — leftover slivers of land that often became small plazas or planted traffic islands, visible evidence of two street systems negotiating the same ground.",
          "map": { "item_id": "81186482d5dd48ca9882593adadd6bfe", "caption": "Hard System Layers: triangular blocks where the diagonal Broadway meets the parallel grid." },
          "claim_ids": ["c1", "c5"]
        },
        {
          "title": "Legacy Today",
          "body": "A century later, the 1,001 segments of this street network still carry the imprint of that negotiation — a planned grid stitched to inherited diagonals, with parks, courtyards, and plazas filling the gaps both left behind.",
          "map": { "item_id": "865dbb45a3b3455590652560174b9ed9", "caption": "Street & Open Space Profile: the full network of 1,001 street segments today." },
          "claim_ids": ["c8"]
        }
      ]
    }
  ]
}
